import { defineConfig } from "vite";

// Single file ESM bundle, for use without a build system:
//   <script type="module"> import { extractShapes } from ".../rdf-lens.min.js"
// Built next to the tsc output, so run this after `npm run build`.
export default defineConfig({
    build: {
        lib: {
            entry: "src/index.ts",
            name: "rdf-lens",
            fileName: () => "rdf-lens.min.js",
            formats: ["es"],
        },
        outDir: "dist",
        emptyOutDir: false,
        sourcemap: false,
        minify: true,
        target: "es2020",
    },
});
